import pageObserversDisconnected from './page-observers-disconnected.mjs';
import syntheticInputEventsBubble from './synthetic-input-events-bubble.mjs';
import syntheticInputEventsTargetAppNode from './synthetic-input-events-target-app-node.mjs';

// host-page-adaptation — being a guest in a web app you do not own: reading its
// DOM, driving it with synthetic input, watching it change, and injecting your
// own UI into it, all against markup that can be redesigned without notice.
//
// Every rule here judges a DOM/API contract that holds for any code driving a
// third-party page — a userscript, a browser automation layer, an extension's
// content script — and its scan is repo-shape agnostic (see lib.mjs `isSource`)
// so it cannot pass vacuously green somewhere laid out differently. It lives
// locally only because the mounted canon has no home for this facet: the
// chrome-extension pack covers MV3 manifest/permission/content-script MECHANICS
// (how to get your code onto the page) and says nothing about what to do once it
// is there, and node / github-actions / chrome-extension-release /
// spec-driven-product / executable-requirements are orthogonal. Declared by hand
// as `local/host-page-adaptation` in .claudinite-settings.json.
export default {
  id: 'host-page-adaptation',
  ruleRoutingGuidance: {
    belongs: 'driving a host web app you don\'t own — its DOM, synthetic input, change watching, injected UI',
    excludes: 'how extension code reaches the page (manifest, permissions, registration) — chrome-extension; speech APIs — local/browser-speech',
  },
  marker: null,
  detect: null,
  prose: 'RULES.md',
  worldRules: [
    pageObserversDisconnected,
    syntheticInputEventsBubble,
    syntheticInputEventsTargetAppNode,
  ],
};
=== README.md ===
# host-page-adaptation pack (local)

A pack for **being a guest in a web app you do not own**: reading its DOM, driving it with
synthetic input, watching it change, injecting your own UI into its chrome, and surviving the
day it is redesigned. Declared by hand as `local/host-page-adaptation` in
`.claudinite-settings.json`.

**Every rule judges a DOM/API contract, not a product decision.** Each one holds for any code
driving a third-party page — a userscript, a browser-automation layer, an extension's content
script — and nothing in a rule's logic, rationale or fix text is specific to this repo. The scan
is repo-shape agnostic (see below), so the pack cannot pass vacuously green somewhere laid out
differently. This repo is where the rules were *discovered* and is the corpus they are verified
against; it is not what they are about.

**Why local, not a canon declaration:** the mounted canon shelf has no home for this facet. The
`chrome-extension` pack covers MV3 *mechanics* — manifest, permissions, how a content script is
registered and why it can't be an ES module — i.e. how your code reaches the page; it says
nothing about what to do once it is there. `chrome-extension-release`, `node`,
`github-actions`, `tidy-repo`, `spec-driven-product`, `executable-requirements` and `barriers`
are orthogonal, and the sibling local pack `browser-speech` owns the speech surfaces, not the
page. Nothing here duplicates a canon rule.

**Provenance:** distilled from this repo's real usage — the whole of
`extension/src/page-adapter/` (`selectors.js`, `reader.js`, `writer.js`, `watcher.js`,
`probe.js`, `splash.js`, `session-button.js`), the REQ-PAGE and REQ-LIFE requirement families
in `dev/docs/REQUIREMENTS.md`, the quarantine rule REQ-PAGE-011 and its arch test
(`extension-test/unit/arch.test.js`), the live-page findings recorded in `writer.js` (MT-02) and
in `selectors.js`'s dated verification notes, and the fake-host fixture
(`extension-test/fixtures/fake-nyt/`). Nothing in it is invented.

**Promotion note:** the checks are written to be lifted as-is — repo-shape agnostic scan, DOM
contracts only, no project identifiers in any rule's logic or messages — so the central promote
stage should be able to move them into a canon pack for this facet (`host-page-adaptation`, or
whatever a canon `html`/DOM pack calls it) with only the `doc:` paths rewritten. The `RULES.md`
prose is the part still worth re-reading for project coupling at promote time: several rules
cite this host's specific behaviours (the ~30 s idle auto-pause, the pencil button with no
readable state) as evidence, and those are examples of a category, not constants.

## Checks

| Check | Enforces (≤5 words) | Severity |
|---|---|---|
| `page-observers-disconnected` | started DOM observers get disconnected | blocking |
| `synthetic-input-events-bubble` | dispatched input events set bubbles | blocking |

**Scope.** Both scan any browser source file (`.js/.mjs/.cjs/.ts/.tsx/.jsx`) except test
and vendor paths — never a hard-coded project root. Each rule is gated on the DOM API it judges
actually appearing in the file, so the API usage *is* the trigger and the scan can be
repo-shaped; a path scope wired to one layout would make every rule match zero files and pass
vacuously green elsewhere, which is the worst failure mode a check has. The exclusion that
matters is test scaffolding: a test dispatching a bare event at its own jsdom node, or spinning
an observer it lets the runner collect, is doing something purpose-built and is not adapting to
a host page.

**Parsed, not grepped, where the name alone doesn't decide it.**

`synthetic-input-events-bubble` judges only events that are actually **dispatched** (a probe
event constructed to feature-detect is not input), only the interfaces that model **real user
input** (a `CustomEvent` is your own signal to your own listener and is legitimately
non-bubbling), and it resolves each side of the dispatch through **one hop**: the constructor
through an alias (`const Ctor = isKey ? view.KeyboardEvent : view.MouseEvent` is how a generic
`fire()` helper is written, and this repo's single dispatch site is exactly that shape), and
the dispatched value through a local (`const ev = new MouseEvent('click');
el.dispatchEvent(ev)` is the other shape real dispatch code takes). An init that spreads
(`{ ...init }`) without an explicit `bubbles:` is beyond what the rule can see, so it stays
silent there: the caller may well set the field, and a check that guessed would false-alarm on
precisely the well-factored helper that centralises this.

**A third check was cut at review.** `synthetic-key-events-legacy-fields` (a synthetic
`KeyboardEvent` init must carry `keyCode`/`which`) enforced a real live-page lesson (MT-02) —
but this repo's only key-event construction builds its init in a helper and spreads it at the
one dispatch site, exactly the shape a spread-silent check can never read. A check that is
structurally blind to the house pattern can only ever fire on code that bypasses the `fire()`
helper, and the mistake in that code is the bypass, not the field it then forgot. The lesson
lands as prose instead (`RULES.md`, "A synthetic keystroke must carry the fields a real one
would").

`page-observers-disconnected` is deliberately **file-scoped, not flow-scoped**: proving a
particular observer is disconnected on every path needs real data-flow analysis, and a check
that guesses is worse than one that asks a simple, honest question — "this file starts an
observer on the page; does it anywhere disconnect one?". An observer constructed but never
`.observe(`d has started nothing and is not asked.

Red-first fixtures live in `pack.test.mjs`: each rule is run against violating sources and
clean ones — in both the direct and the aliased-constructor form, in TypeScript under a plain
`src/` as well as JavaScript — and then against this repo's real `extension/src/` tree, which
must stay quiet. The project's vitest run picks the file up via the
`.claudinite/local/packs/**/*.test.mjs` include in `vitest.config.js`, so the checks ship green
in CI.

**When a check's whole point is precision, red-first has to prove it in two directions.** A
violating fixture failing and a clean one passing only proves the shipped check is correct — it
says nothing about whether the parsing it does was *necessary*. So the quiet fixtures are also
run against the naive alternative each piece of parsing exists to avoid, and confirmed to fire
there: a whole-file `new …Event(` grep wrongly flags the `CustomEvent`, never-dispatched and
already-bubbling cases.

## Prose (`RULES.md`)

| Rule (≤5 words) | How enforced |
|---|---|
| quarantine host DOM in one module | prose |
| identify host UI by nets | prose |
| date what selectors were verified against | prose |
| probe reports, never throws | prose |
| mirror the host in a fixture | prose |
| never trust a write; re-read | prose |
| synthetic keystrokes carry real-event fields | prose (its bubbles half is checked) |
| restore borrowed host state; degrade | prose |
| host lifecycle states aren't user actions | prose |
| be inert when off | prose (its observer teardown is checked) |
=== references.md ===
# References — rationale behind this pack's rules and checks

Maintenance and review material for the `writing-pack-prose` references convention: each entry
carries the reason a rule or check exists, written so a periodic review can reaffirm — or
retire — it. Entry keys are file-scoped stable identifiers (gaps allowed, never renumbered): an
end-of-line `(n)` marker in `RULES.md` cites `RULES-n`, one in a skill cites
`<skill-name>-n`, and `check:` entries cover checks. No session loads this file for daily work.

- **(RULES-1)** Verified live against nytimes.com during MT-02 (`dev/docs/MANUAL-TESTS.md`, the
  answer-injection go/no-go test): a bare `{key}`-only `KeyboardEvent` constructs `keyCode` and
  `which` as `0`, and the live app's key-handling layer branched on those legacy fields rather
  than `key`/`code`, so the synthetic keystroke silently matched nothing — recorded as a
  live-page hardening finding in `extension/src/page-adapter/writer.js`. Reaffirm against
  nytimes.com's markup and handlers; retire only if a re-verification shows the live handler now
  reads `key`/`code` instead of the legacy fields.
=== VERSIONS.md ===
# Version history

The record of what an automatic growth task has changed in this pack, one row per change,
newest on top. Not a version-bump log — local packs carry no `version` field — just what
landed and why.

| Date | Task | What changed |
|---|---|---|
| 2026-08-30 | prose-to-checks-sweep | The "aim your events at a node inside the app's own subtree ... an event dispatched at `document` or `body` bubbles past it and is never seen" rule in RULES.md's "Never trust a write" section converts to the `synthetic-input-events-target-app-node` check; the covered sentence is deleted from the prose. |
=== pack.test.mjs ===
// Red-first fixtures for the host-page-adaptation pack's checks.
//
// Every rule is exercised three ways: it must FIRE on a violating source, stay
// QUIET on a clean one, and stay quiet on the repo's real extension/src/ tree.
// The third case is what makes the pack shippable — a check that only ever saw
// its own fixtures is a check nobody has confronted with real code.
//
// Runs in the project's own vitest (see the .claudinite/local/packs include in
// vitest.config.js) and imports nothing from the gitignored canon mount, so it
// works in CI exactly as it does locally.

import { describe, test, expect } from 'vitest';
import { readdirSync, readFileSync, statSync } from 'node:fs';
import { join, relative, sep } from 'node:path';

import pack from './pack.mjs';
import { isSource } from './lib.mjs';
import pageObserversDisconnected from './page-observers-disconnected.mjs';
import syntheticInputEventsBubble from './synthetic-input-events-bubble.mjs';
import syntheticInputEventsTargetAppNode from './synthetic-input-events-target-app-node.mjs';

// A check context over a literal file map — the same {files, read} surface the
// engine's runner passes, with nothing else the rules are allowed to touch.
const ctxOf = (files) => ({
  files: Object.keys(files),
  read: (f) => (f in files ? files[f] : null),
});

const run = (rule, files) => rule.run(ctxOf(files));

describe('host-page-adaptation pack manifest', () => {
  test('is a hand-declared local pack whose rules are all wired', () => {
    expect(pack.id).toBe('host-page-adaptation'); // must equal the directory name
    expect(pack.detect).toBeNull();
    expect(pack.marker).toBeNull();
    expect(pack.prose).toBe('RULES.md');
    expect(pack.worldRules.map((r) => r.id).sort()).toEqual([
      'page-observers-disconnected',
      'synthetic-input-events-bubble',
      'synthetic-input-events-target-app-node',
    ]);
  });
});

// The scan must be repo-shape agnostic: a rule that only ever looks under one
// project's source root matches nothing — and passes vacuously green — in a repo
// laid out differently, which is exactly the bug these cases exist to prevent.
describe('source scope', () => {
  test('accepts browser source under any layout, in JS and TS alike', () => {
    for (const file of [
      'extension/src/page-adapter/writer.js',
      'src/adapter.ts',
      'app/lib/host.tsx',
      'packages/web/inject.mjs',
      'userscript.cjs',
    ]) expect(isSource(file), file).toBe(true);
  });

  test('rejects test scaffolding, fixtures and vendored code wherever they sit', () => {
    for (const file of [
      'extension-test/integration/page-adapter.test.js',
      'extension-test/fixtures/fake-nyt/fake-app.js',
      'src/adapter.spec.ts',
      'test/host.js',
      'node_modules/x/index.js',
      'dist/content.js',
      'README.md',
    ]) expect(isSource(file), file).toBe(false);
  });
});

describe('page-observers-disconnected', () => {
  test('fires on an observer started and never disconnected', () => {
    const found = run(pageObserversDisconnected, {
      'src/mount.js': `
        export function watch(document, onChange) {
          const observer = new MutationObserver(onChange);
          observer.observe(document.body, { childList: true, subtree: true });
        }
      `,
    });
    expect(found.map((f) => f.rule)).toEqual(['page-observers-disconnected']);
    expect(found[0].file).toBe('src/mount.js');
    expect(found[0].severity).toBe('blocking');
  });

  test('fires on an IntersectionObserver and a ResizeObserver too', () => {
    for (const cls of ['IntersectionObserver', 'ResizeObserver']) {
      const found = run(pageObserversDisconnected, {
        'app/host.ts': `const o = new ${cls}(cb); o.observe(el);`,
      });
      expect(found.length, cls).toBe(1);
    }
  });

  test('fires when the observer is constructed off a window reference', () => {
    const found = run(pageObserversDisconnected, {
      'src/mount.js': `
        const view = document.defaultView;
        const observer = new view.MutationObserver(schedule);
        observer.observe(document.documentElement, { subtree: true, childList: true });
      `,
    });
    expect(found.length).toBe(1);
  });

  test('quiet when the observer disconnects (one-shot mount)', () => {
    const found = run(pageObserversDisconnected, {
      'src/mount.js': `
        export function mountWhenReady(document, place) {
          const observer = new MutationObserver(() => {
            const host = document.querySelector('[class*="toolbar"]');
            if (!host) return;
            observer.disconnect();
            place(host);
          });
          observer.observe(document.documentElement, { childList: true, subtree: true });
        }
      `,
    });
    expect(found).toEqual([]);
  });

  test('quiet when an observer is constructed but never started', () => {
    const found = run(pageObserversDisconnected, {
      'src/factory.js': 'export const makeObserver = (cb) => new MutationObserver(cb);',
    });
    expect(found).toEqual([]);
  });

  test('quiet on a comment that merely names the trap', () => {
    const found = run(pageObserversDisconnected, {
      'src/notes.js': `
        // A MutationObserver started here would need observer.observe(...) and
        // an observer.disconnect() in teardown.
        export const nothing = 1;
      `,
    });
    expect(found).toEqual([]);
  });

  test('quiet in test scaffolding that leaves its observer to the runner', () => {
    const found = run(pageObserversDisconnected, {
      'test/watch.test.js': 'const o = new MutationObserver(cb); o.observe(document.body, {});',
    });
    expect(found).toEqual([]);
  });
});

describe('synthetic-input-events-bubble', () => {
  test('fires on an input event dispatched with no init at all', () => {
    const found = run(syntheticInputEventsBubble, {
      'src/drive.js': "el.dispatchEvent(new MouseEvent('click'));",
    });
    expect(found.map((f) => f.rule)).toEqual(['synthetic-input-events-bubble']);
    expect(found[0].what).toContain('MouseEvent');
  });

  test('fires on an init that omits bubbles', () => {
    const found = run(syntheticInputEventsBubble, {
      'src/drive.js': "target.dispatchEvent(new KeyboardEvent('keydown', { key: 'A', keyCode: 65, which: 65 }));",
    });
    expect(found.length).toBe(1);
  });

  test('fires on an explicit bubbles: false', () => {
    const found = run(syntheticInputEventsBubble, {
      'src/drive.js': "el.dispatchEvent(new PointerEvent('pointerdown', { bubbles: false, cancelable: true }));",
    });
    expect(found.length).toBe(1);
  });

  test('fires through a one-hop constructor alias — the generic fire() helper', () => {
    const found = run(syntheticInputEventsBubble, {
      'src/drive.js': `
        function fire(el, type, init) {
          const Ctor = type.startsWith('key') ? window.KeyboardEvent : window.MouseEvent;
          el.dispatchEvent(new Ctor(type, { cancelable: true, composed: true }));
        }
      `,
    });
    expect(found.length).toBe(1);
  });

  test('fires through one variable hop — built into a local, dispatched by name', () => {
